(function () {
  "use strict";

  const artworks = [{"id":"01","image":"assets/art/01.jpg","name":"Yunduo","diagnosis":"Hepatoblastoma","dateCreated":"October 25, 2025","description":"Yunduo, born in May 2020 and nicknamed “Tangyuan,” is from Guangzhou. She was diagnosed with hepatoblastoma and is currently receiving treatment at Sun Yat-sen University Cancer Center.","session":1,"sessionOrderPosition":1,"age":"6 years old","ageOrderPosition":6},{"id":"02","image":"assets/art/02.jpg","name":"Yuanming","diagnosis":"Neuroblastoma","dateCreated":"October 25, 2025","description":"Yuanming is a 7-year-old boy from Zhangjiajie, Hunan. He was diagnosed with neuroblastoma in May 2025 and is currently receiving treatment at Sun Yat-sen University Cancer Center.","session":1,"sessionOrderPosition":2,"age":"7 years old","ageOrderPosition":7},{"id":"03","image":"assets/art/03.jpg","name":"Yueyue","diagnosis":"Neuroblastoma","dateCreated":"October 25, 2025","description":"Yueyue is a boy from Guangxi, born in December 2021. He was diagnosed with neuroblastoma in March 2025 and is currently receiving maintenance therapy at Sun Yat-sen University Cancer Center.","session":1,"sessionOrderPosition":3,"age":"4 years old","ageOrderPosition":3},{"id":"04","image":"assets/art/04.jpg","name":"Yanzi","diagnosis":"Ewing sarcoma","dateCreated":"October 25, 2025","description":"Yanzi is a 17-year-old girl from Ganzhou, Jiangxi. She was diagnosed with Ewing sarcoma in February 2025 and is currently receiving treatment at Sun Yat-sen University Cancer Center.","session":1,"sessionOrderPosition":4,"age":"17 years old","ageOrderPosition":26},{"id":"05","image":"assets/art/05.jpg","name":"Lin","diagnosis":"Carcinoma","dateCreated":"November 29, 2025","description":"Lin, born in March 2013, is from Lufeng, Guangdong. She was diagnosed with carcinoma in May 2025 and has now entered the follow-up and rehabilitation stage. Throughout her treatment, her mother remained by her side","session":2,"sessionOrderPosition":5,"age":"13 years old","ageOrderPosition":19},{"id":"06","image":"assets/art/06.jpg","name":"Min","diagnosis":"Ewing Sarcoma","dateCreated":"November 29, 2025","description":"Min is from Yichun, Jiangxi, and was born in April 2011. She was diagnosed with Ewing sarcoma in April 2025 and has now entered the follow-up and rehabilitation stage. During her treatment, her older sister, who had just graduated from university, remained by her side.","session":2,"sessionOrderPosition":6,"age":"15 years old","ageOrderPosition":24},{"id":"07","image":"assets/art/07.jpg","name":"Lin","diagnosis":"Lymphoma","dateCreated":"November 29, 2025","description":"Lin is a boy from Guangzhou, born in December 2009. He was diagnosed with lymphoma in August 2024 and is currently undergoing regular follow-up and rehabilitation. Throughout his treatment, his mother and older sister have remained by his side.","session":2,"sessionOrderPosition":7,"age":"16 years old","ageOrderPosition":25},{"id":"08","image":"assets/art/08.jpg","name":"Bin","diagnosis":"Medulloblastoma","dateCreated":"November 29, 2025","description":"Bin was born in September 2018 and was diagnosed with medulloblastoma in June 2023. He received treatment at Guangdong Sanjiu Brain Hospital. Sadly, Xiaobin has passed away.","session":2,"sessionOrderPosition":8,"age":"7 years old","ageOrderPosition":9},{"id":"09","image":"assets/art/09.jpg","name":"Li Siying","diagnosis":"Nasopharyngeal Carcinoma","dateCreated":"January 24, 2026","description":"14-year-old Li Siying, from Zhaotong, Yunnan, was diagnosed with nasopharyngeal carcinoma. A lump behind her ear was initially misdiagnosed as lymphadenitis. For nearly a year, the family tried warm compresses and folk remedies, but the lump did not improve. A later biopsy at Yunnan University Hospital in Kunming showed a 90% likelihood of malignancy. On the recommendation of her local doctor, mother and child traveled from Zhaotong to Guangzhou for specialized treatment at Sun Yat-sen University Cancer Center. During the first round of chemotherapy, the child developed a fever of 40°C that lasted for three days. After several setbacks, the condition stabilized, and treatment progressed.\nThis is a single-parent family. The father died ten years ago, before the younger child was born. For years, the mother worked alone to support her two children. Despite financial hardship, she never gave up. During chemotherapy breaks, she even worked 24-hour elder-care shifts to cover rent and living expenses. Later, through a chance act of kindness, she learned about the “Little Home” and received accommodation and financial assistance. She said that what mattered most was not simply saving on rent, but knowing that “there is a group of people behind me”. There are people who could guide her whenever she felt lost.\nThere were moments when she broke down, especially when her Siying could not eat, and her efforts seemed fruitless. Yet she would tell herself, “Don’t look at the hundreds of steps ahead. Just take the first step in front of you.” She enjoys listening to stories about ancient Chinese poets, such as Li Qingzhao, Li Bai, and Du Fu, and copying classical Chinese poetry, which gives her a temporary escape from reality. Before bed, she asks herself: Why am I sad? What can I do about it? If nothing can be done, she simply tells herself, “Let it go. Go to sleep.”\nTo her, the painting created by her child represents “the beginning of a new life.” Mother and Siying even discussed changing their names and starting anew. She hopes the painting will preserve their years of treatment and remind them to keep moving forward, one step at a time.","session":3,"sessionOrderPosition":9,"age":"14 years old","ageOrderPosition":23},{"id":"10","image":"assets/art/10.jpg","name":"Enjie","diagnosis":"Neuroblastoma","dateCreated":"January 24, 2026","description":"Enjie is three years old and comes from Guangxi. At an age when she loves Ultraman, she faces hospitals, treatments, and unfamiliar experiences. Rather than frightening her with complicated medical knowledge, her mother tells her, “We are going to defeat the monsters.” Treatment has therefore become a “battle” that requires courage.\nEnjie was classified as a high-risk patient and needs chemotherapy, radiotherapy, transplantation, and immunotherapy. Immunotherapy is particularly expensive: based on her weight, one course requires three doses costing about RMB 120,000, and several courses may be necessary. Her mother has worked hard to raise money so that they can pursue every possible treatment. During the first one or two months, she experienced significant emotional distress, but gradually learned to accept reality and face treatment more positively.\nEnjie’s young age has also brought an unexpected kind of strength. She does not dwell on the fact that she is sick. Needles hurt and treatment is difficult, but she rarely allows these experiences to become prolonged sadness. Her mother is therefore spared some of the psychological burden and can accompany her more calmly.\nEnjie Mother’s own life leaves almost no time for rest. Hospital visits, childcare, and preparing meals fill nearly every day. At the “Little Home,” this was her first opportunity to participate in an art activity. She hopes the painting will become a precious memory of time shared with her child. More importantly, she hopes society will recognize that families are also fighting their own battle, carrying enormous psychological and financial burdens.","session":3,"sessionOrderPosition":10,"age":"3 years old","ageOrderPosition":1},{"id":"11","image":"assets/art/11.jpg","name":"Lu Shidong","diagnosis":"Neuroblastoma","dateCreated":"February 27, 2026","description":"Lu Shidong, from Huizhou, Guangdong, developed sudden leg pain at age eight. A local clinic initially attributed it to a joint problem. After the pain persisted, an MRI at Huizhou People’s Hospital showed abnormalities in the bone, but the hospital could not make a definitive diagnosis. The family then came to Guangzhou, where he was diagnosed with neuroblastoma and immediately began treatment.\nThe family soon faced both medical and financial challenges. Immunotherapy could cost more than RMB 1 million based on the child’s size. With limited income, his father works while his mother cares for their three children. They ultimately chose conventional treatment supplemented by other therapies according to his condition. He has now entered the radiotherapy stage.\nOn the night of diagnosis, mother and son held each other and cried. Yet the child soon comforted her: “Mom, don’t cry. We will definitely get better.” He has always been unusually considerate. Once, he even saved his breakfast money to buy his younger brother a pair of three-yuan gloves. Facing a long treatment journey, his mother tells herself that she cannot spend all her energy on anxiety. “This is a long battle.” She sleeps when it is time to sleep, talks when it is time to talk, and focuses on the next step.\nShe hopes the painting will serve as a reminder of this “long-term battle.” She wants to keep it for the future and look back on how her child gradually recovered. To her, the child in the painting is not defined by illness, but is a child growing again and returning to a healthy life.","session":4,"sessionOrderPosition":11,"age":"8 years old","ageOrderPosition":11},{"id":"12","image":"assets/art/12.jpg","name":"Wang Xiaoran","diagnosis":"Brain Tumor","dateCreated":"February 27, 2026","description":"Wang Xiaoran is 13 years old. She is from Hubei and lives with her family in Dongguan. She initially sought medical care for recurring headaches before doctors discovered a brain tumor. By the time of diagnosis, the tumor had grown large and was compressing the brainstem, making surgery highly risky.\nHer family struggled over whether to transfer her to Guangzhou. Although local doctors warned about the risks of transferring her, her mother ultimately chose Guangzhou for access to better treatment. After surgery, the child was temporarily unable to walk, and her left hand and leg were affected. Her mother recalls crying repeatedly, but once surgery was over, there was little time for grief. Caring for her child and watching her recovery became her entire life. Today, Xiaoran can slowly walk on her own. She is still unsteady, but every small improvement brings comfort.\nThe mother did not initially explain the full seriousness of the disease to her child. She began with simple reassurance that “After the surgery, you’ll get better”, and allowed her to gradually understand her condition through treatment. Xiaoran has remained relatively optimistic.\nAt the welfare housing, the mother found more than convenient accommodation. She found reassurance in knowing that “people are going through this with us.” Parents exchange experiences, while children can talk and play together.\nShe joined the painting activity so her child could exercise, interact with others, and leave behind a memory of this unusual period. She hopes the painting captures her child as she is now and records her journey from being unable to walk to gradually recovering. Every improvement is a reason to keep moving forward.","session":4,"sessionOrderPosition":12,"age":"13 years old","ageOrderPosition":18},{"id":"13","image":"assets/art/13.jpg","name":"Dai Xingchen","diagnosis":"Neuroblastoma","dateCreated":"February 27, 2026","description":"Dai Xingchen is from Hunan and is four years and eight months old. When he first came to Guangzhou, he was excited and kept urging his mother, “Hurry up!” But as treatment continued, he gradually became tired of the repeated procedures. After nearly eight months of treatment, he has now entered the final stage of immunotherapy, and his hair has begun to grow back.\nHis mother has spent months traveling back and forth for treatment. In the past, they would return to Hunan after each session, then come back to Guangzhou several days before examinations and stay in hotels. She also had to travel between cities to complete reimbursement procedures. After moving into the “Little Home,” accommodation became easier, and the companionship of other families helped her feel less isolated.\nHer daily life remains extremely busy—going to the hospital, buying groceries, caring for her child—and she often has no free time until after nine at night. Still, occasional hot-pot dinners or conversations with other parents provide small moments of rest.\nFor her, the art activity was another rare opportunity to relax. She hopes the painting will preserve this special period as treatment approaches its end and that Xingchen will grow up healthy and happy. The child in the painting is beginning to recover, just as Xingchen in real life is gradually growing his hair back and returning to ordinary life.\nMother: “Stay strong. Keep going. Keep fighting. Stay optimistic.”","session":4,"sessionOrderPosition":13,"age":"4 years 8 months old","ageOrderPosition":4},{"id":"14","image":"assets/art/14.jpg","name":"Chen Jianrong","diagnosis":"Medulloblastoma","dateCreated":"February 27, 2026","description":"Chen Jianrong, a 10-year-old boy, is from Huizhou, Guangdong. After his diagnosis, he underwent surgery locally. Because the hospital lacked appropriate radiotherapy facilities for children, doctors recommended continuing treatment at Sun Yat-sen University Cancer Center in Guangzhou. He has since undergone surgery, radiotherapy, and chemotherapy. After nearly two years of treatment, his plan has been adjusted according to his blood counts: when he is stronger, he follows a 28-day regimen; when he needs more recovery time, a 42-day regimen is used.\nAt first, the family did not know about the welfare housing. During radiotherapy, they rented a place near the hospital, spending more than RMB 10,000 in just a month and a half. Later, through other families, they applied to stay at the welfare housing, where they received free accommodation and daily necessities such as rice, oil, and salt. This significantly reduced the family’s financial and practical burden.\nThe mother remembers the earliest period after diagnosis as especially difficult. Over time, meeting other families with similar experiences helped her realize that she was not alone. Parents exchanged treatment experiences, and children played together. This companionship gradually eased her fear and helped her accept reality: “Since it has already happened, all we can do is actively cooperate with treatment.”\nShe spends almost all her time caring for her child. She joined the art activity mainly to spend more time with him and create a special memory. Jianrong even told her, “You have to draw me beautifully.” The painting therefore became more than an artwork. It became a record of the years they had gone through together.","session":4,"sessionOrderPosition":14,"age":"10 years old","ageOrderPosition":15},{"id":"15","image":"assets/art/15.jpg","name":"Zheng Renxuan","diagnosis":"Medulloblastoma","dateCreated":"March 28, 2026","description":"Three-and-a-half-year-old Zheng Renxuan, known as Xuanxuan, is from Guangxi. After his diagnosis, his family came to Guangzhou rather than remaining in their hometown. His mother believed that a major city could offer greater medical expertise and more surgical experience. Even if the final outcome were the same, she wanted to reduce treatment risks and “give him a new chance and new hope.”\nIn Guangzhou, rent, food, transportation, and medications became major financial burdens. When they stayed at the welfare housing, free accommodation and daily necessities eased much of the pressure. They could also apply for material assistance when needed.\nBecause Xuanxuan is so young, his mother has never directly told him that he has a tumor. She describes treatment simply as being sick and getting better. She believes that parental emotions affect children, so she tries to remain positive. Yet caregiving is exhausting. Xuanxuan needed help with walking and eating, leaving her responsible for almost everything. When exhaustion made her lose her temper, she would later hug him and explain, “Mom is tired too. I didn’t mean to be angry with you.” Over time, Xuanxuan began to notice her emotions, asking, “Mom, are you happy?” and saying, “Mommy, I love you,” or “Let me rub your back.” These small gestures have become her greatest comfort.\nPainting gives the mother a rare space of her own. She likes using vivid acrylic colors to express the idea of “growing toward the light,” and she has donated dozens of paintings to hospitals. She especially treasures Xuanxuan’s former bright smile, which has been difficult to see since surgery. Through this painting, she hopes to preserve his happiest image and the precious time they shared.\nDuring his prolonged ICU stay, she once noticed that Xuanxuan was afraid his parents would abandon him. She recorded a song, Don’t Panic, There Is Still Moonlight After the Sun Goes Down, and played it for him repeatedly, hoping to tell him, “We have not abandoned you.”","session":5,"sessionOrderPosition":15,"age":"3.5 years old","ageOrderPosition":2},{"id":"16","image":"assets/art/16.jpg","name":"Yanjun","diagnosis":"Medulloblastoma","dateCreated":"March 28, 2026","description":"Yanjun’s family traveled a long distance from Xinjiang for her treatment. At nine and a half, she underwent surgery, radiotherapy, and chemotherapy. Her parents recall that the most difficult period was radiotherapy after surgery. Her body was already weak, and her platelet counts recovered slowly. For nearly a month and a half, they traveled to the hospital almost every day for injections and follow-up examinations, leaving little time to rest.\nThe decision to come to Guangzhou was relatively straightforward because her condition was urgent. Her tumor was located in the cerebellum and required surgery as soon as possible. The greater challenge was the long and repetitive treatment that followed.\nLong-term treatment away from home created significant costs, including rent, daily expenses, and transportation between Xinjiang and Guangzhou. Fortunately, the family later stayed at the welfare housing, where they received daily necessities and participated in activities such as visiting an aquarium and a science and nature museum. These experiences gave Yanjun brief moments away from hospitals and pain.\nShe knows she is sick. Her mother explains it simply: “We just need to drive the monster away.” From surgery through radiotherapy and chemotherapy, Yanjun has cooperated remarkably well and rarely complains even when she feels unwell. She has already begun planning life after recovery: returning to school and taking art classes again. Her mother once felt that “the sky had collapsed on top of them,” but she kept her hardest emotions for herself and continued telling her daughter that things would gradually improve.\nYanjun loves drawing. Her mother hopes this painting will allow her to draw herself and imagine life after the “monster” is gone. For the family, art therapy means allowing the child to experience happiness beyond treatment and giving the family a chance to create something together.","session":5,"sessionOrderPosition":16,"age":"9.5 years old","ageOrderPosition":13},{"id":"17","image":"assets/art/17.jpg","name":"Ou","diagnosis":"Rhabdomyosarcoma","dateCreated":"March 28, 2026","description":"Ou, 14, is from Maoming, Guangdong. Her family went through a long and complicated search for appropriate treatment. Treatment in her hometown was initially unsuccessful. After being diagnosed at a provincial hospital, they explored other options before eventually coming to Guangzhou.\nHer tumor was located at the base of the skull, and treatment focused mainly on radiotherapy and chemotherapy. At one point, the disease severely affected one eye. After treatment, she was able to preserve vision in one eye, which her family considers one of the greatest pieces of good news along the way.\nLong-term treatment away from home created additional costs, especially rent and daily living expenses. After moving into the welfare housing, the family’s financial burden was greatly reduced, and they also received daily necessities and nutritional support. The House gave them more than financial relief: it also provided companionship. Families helped one another, passing kindness from those who had just arrived to newcomers who needed support.\nOu knows she has a tumor, but her parents have not discussed the risks in detail. She remains focused on returning to her familiar life. Because her parents had limited time with her before her illness, the treatment period unexpectedly gave them more time together. Whenever her health allowed, they drew, talked, took photographs, and joined activities. These shared moments became precious memories.\nFor her mother, the greatest value of the painting was to “preserve the present moment.” Because Ou’s memory has been affected, her mother especially treasures each day and tries to take photographs and participate in activities whenever possible. She hopes the painting will preserve her child’s appearance and this period of their lives together.","session":5,"sessionOrderPosition":17,"age":"14 years old","ageOrderPosition":22},{"id":"18","image":"assets/art/18.jpg","name":"Ruirui","diagnosis":"Burkitt Lymphoma","dateCreated":"June 18, 2026","description":"Ruirui is a boy from Guangzhou, born in February 2021. He was diagnosed with Burkitt lymphoma in March 2026 and is currently receiving chemotherapy at Sun Yat-sen University Cancer Center.","session":6,"sessionOrderPosition":18,"age":"5 years old","ageOrderPosition":5},{"id":"19","image":"assets/art/19.jpg","name":"Yanyan","diagnosis":"Rhabdomyosarcoma","dateCreated":"June 18, 2026","description":"Yanyan is from Guangzhou and was born in December 2016. She was diagnosed with rhabdomyosarcoma in July 2025. Her condition is currently stable, and she is receiving treatment at Sun Yat-sen University Cancer Center.","session":6,"sessionOrderPosition":19,"age":"9 years old","ageOrderPosition":12},{"id":"20","image":"assets/art/20.jpg","name":"Yueyue","diagnosis":"Medulloblastoma","dateCreated":"June 18, 2026","description":"Yueyue is a girl from Guangzhou and was born in June 2016. She is currently receiving chemotherapy at Sun Yat-sen University Cancer Center. She has been diagnosed with medulloblastoma and remains in active treatment.","session":6,"sessionOrderPosition":20,"age":"10 years old","ageOrderPosition":14},{"id":"21","image":"assets/art/21.jpg","name":"Xuan","diagnosis":"Medulloblastoma","dateCreated":"June 18, 2026","description":"Xuan is a girl from Guangzhou, born in July 2018. She was diagnosed with medulloblastoma in January 2026. Her condition is currently stable, and she is receiving treatment at Sun Yat-sen University Cancer Center.","session":6,"sessionOrderPosition":21,"age":"8 years old","ageOrderPosition":10},{"id":"22","image":"assets/art/22.jpg","name":"Huang Huili","diagnosis":"Alveolar Rhabdomyosarcoma","dateCreated":"August 7, 2026","description":"Huang Huili is from Heyuan, Guangdong, and is about to turn 11. In October 2024, a small lump appeared on the sole of her foot. At first, her family thought it was an injury from dancing or an ordinary growth. It was only after surgery, when pathology revealed a malignant tumor, that she was brought to Guangzhou for further treatment. She was diagnosed with alveolar rhabdomyosarcoma and has since undergone surgery, chemotherapy, and radiotherapy, completing more than twenty rounds of treatment. Her family had originally expected treatment to end in October 2025, but follow-up examinations revealed new lesions in her ribs, back, and other areas. She therefore had to continue treatment. In May this year, she underwent another surgery and is still receiving chemotherapy and radiotherapy. The prolonged treatment has also caused side effects, including bone marrow suppression and difficulty recovering her platelet count.\nHer mother remembers one twelve-hour surgery most vividly. She waited alone outside the operating room, overwhelmed by anxiety and helplessness. After the operation, Huang Huili needed to remain lying down for a long time and could not walk because of the surgery on her leg. The family struggled to find suitable accommodation until they were able to move into welfare housing near the hospital, which greatly eased their daily difficulties. To help her daughter cope, her mother has always explained the illness in simple terms: “Once you finish the medicine, you can go home, and everything will be fine.”\nThrough this painting, she hopes to preserve the image of her daughter as she once was—healthy and full of life. She dreams that Huang Huili will one day have her hair back, stop traveling between home and hospital, and return to a healthy, carefree life. She also hopes there will be more parent-child art activities, giving families moments of connection and ease beyond treatment.","session":7,"sessionOrderPosition":22,"age":"11 years old","ageOrderPosition":16},{"id":"23","image":"assets/art/23.jpg","name":"Xie Yuequn","diagnosis":"Embryonal Rhabdomyosarcoma","dateCreated":"August 7, 2026","description":"Seventeen-year-old Xie Yuequn is from Guizhou. She first sought medical attention after a lump developed on her buttock. Her family initially thought it was an ordinary abscess, but abnormal tissue was found during surgery, and pathology revealed a malignant tumor. They then traveled to Chongqing for further diagnosis. She was eventually diagnosed with embryonal rhabdomyosarcoma and, on medical advice, came to Guangzhou for treatment.\nShe is now receiving care at Sun Yat-sen University Cancer Center. After prolonged chemotherapy, the tumor has continued to grow and ulcerate, with metastases in the lymph nodes and lungs. Because of its location and size, neither surgery nor radiotherapy currently offers a suitable option, so she must continue chemotherapy. She has experienced vomiting, hair loss, and severe anemia. Recently, her anemia became so severe that she suddenly lost all strength and was unable to walk.\nFor her family, the most desperate moment came when chemotherapy failed to produce the expected results. Doctors evaluated radiotherapy and surgery separately, but concluded that both carried risks too high to justify. Faced with this reality, the family could only support one another by talking with other patients’ families and exercising or climbing stairs to relieve stress. To protect Yuequn, they initially did not tell her the full severity of her condition, but as treatment continued, she gradually realized what was happening.\nThis painting carries a strong wish to preserve a memory. The girl in it represents Yuequn before she became ill, with long hair and a healthy, beautiful appearance. Her family hopes to preserve that image in a frame as a keepsake. For Yuequn and her family, experiencing art therapy for the first time was both new and enjoyable. More importantly, painting gave them a temporary escape from the pressure of illness and treatment, allowing them to focus on something creative and meaningful together.","session":7,"sessionOrderPosition":23,"age":"17 years old","ageOrderPosition":27},{"id":"24","image":"assets/art/24.jpg","name":"Yuanyuan","diagnosis":"Gray-zone Lymphoma","dateCreated":"August 7, 2026","description":"Seventeen-year-old Yuanyuan is from Shaoyang, Hunan. In January 2026, he began experiencing persistent chest pain. He was initially treated locally for pleurisy, but when the pain failed to improve, examinations revealed a mediastinal tumor more than ten centimeters in size. His family traveled between hospitals in Hunan, Guangzhou, and Shanghai, undergoing more than a month of tests before he was diagnosed with gray-zone lymphoma, an intermediate tumor with features of both Hodgkin and non-Hodgkin lymphoma. He is now receiving targeted monoclonal antibody therapy combined with chemotherapy at Sun Yat-sen University Cancer Center. After five cycles, the tumor has continued to shrink, and his condition remains stable.\nYuanyuan’s mother remembers the confusion and panic she felt when she first arrived in Guangzhou alone with her child. She did not know where the hospital was or what the future would bring. Fortunately, a kind landlord helped carry their luggage and brought them to their temporary home. Later, a charitable organization helped the family move into a small apartment, easing their housing and financial burdens.\nThe most overwhelming period was the long wait for a diagnosis. Afraid that her child might have an untreatable illness, she often hid away to cry. To release stress, she climbed from the 20th to the 40th floor with other parents, letting the night wind cool her face before returning to the ward. Yuanyuan understands his illness, and his mother hopes he remains confident in recovery.\nUnlike many parents, she did not see the painting only as a wish for health. She wanted to preserve this difficult chapter so Yuanyuan could one day look back and know they made it through. She hopes this hardship will become a trace of the past: once they cross this hurdle, there will be light ahead. Painting also helped her step away from reality and express her thoughts, and she hopes to record more of her child’s life through art.","session":7,"sessionOrderPosition":24,"age":"17 years old","ageOrderPosition":28},{"id":"25","image":"assets/art/25.jpg","name":"En","diagnosis":"Malignant Peripheral Nerve Sheath Tumor (MPNST)","dateCreated":"August 7, 2026","description":"En is from Jieyang, Guangdong, and is about to turn 12. At the beginning of 2026, he began experiencing pain in his thigh. His family initially thought it was growing pains or a muscle strain, but the pain gradually worsened, and a hard mass was discovered in his abdomen. After further examination in Guangzhou, including pathological and genetic testing, he was diagnosed with a malignant peripheral nerve sheath tumor (MPNST). He is currently receiving treatment at Sun Yat-sen University Cancer Center. He has completed several rounds of chemotherapy and is now undergoing radiotherapy, with additional chemotherapy still to come. Because the tumor has invaded his lumbar spine, some lesions cannot be completely removed through surgery, so his treatment plan requires evaluation by multiple medical departments. Chemotherapy has caused nausea, poor appetite, and fatigue, and he also needs treatment to help restore his white blood cell count.\nFor his mother, the hardest moments come during follow-up examinations. After surgery and chemotherapy, she longs to hear that he is improving, yet she has repeatedly been told that “it has grown again” or that “new lesions have appeared.” Those moments, she says, leave her devastated and helpless. When alone, she sometimes hides away to cry, even letting herself cry in the shower before going outside for a walk. More often, she reminds herself to “take it one step at a time.” Knowing that they have found capable doctors, she focuses on doing whatever can be done.\nEn has also begun to understand his illness. Once, he asked his mother, “Why does everyone have to die?” She explained that birth, aging, illness, and death are part of every person’s life.\nShe hopes the En in the painting will one day recover, return to school and home, and live a normal life again. For her, painting is also a form of emotional release: when she becomes fully immersed in it, she can temporarily set aside the pressure of treatment. She hopes there will be more opportunities like this for families to rest, create, and breathe.","session":7,"sessionOrderPosition":25,"age":"12 years old","ageOrderPosition":17},{"id":"26","image":"assets/art/26.jpg","name":"Lin Zixuan","diagnosis":"B-cell Acute Lymphoblastic Leukemia","dateCreated":"August 21, 2026","description":"Thirteen-year-old Lin Zixuan is from Yangjiang, Guangdong. On June 28 this year, he was diagnosed with B-cell acute lymphoblastic leukemia. During an initial examination locally, doctors found that he was severely anemic and suspected leukemia, so his family brought him to Zhujiang Hospital of Southern Medical University in Guangzhou. He is currently receiving chemotherapy and has entered the first half of his second treatment cycle.\nWhen he arrived at the hospital, Zixuan was severely anemic and required nine units of blood transfusion, delaying the start of his first chemotherapy cycle. A typical cycle usually requires about 33 days of hospitalization, but his first treatment lasted nearly 40 days, and he experienced two hospital admissions. For a family just beginning to face cancer, the experience was overwhelming. His mother says that once the diagnosis was confirmed, they could only try to “stay optimistic.” She still feels sad at times, but chooses to devote most of her energy to accompanying her son through treatment. At night, when she has free time, she listens to music to briefly relax.\nAt 13, Zixuan is gradually entering an age when he talks less with his parents. His mother says that as he grows older, he is less willing to tell his family what is on his mind. For her, therefore, the painting activity meant more than simply creating a picture. It gave mother and son a rare opportunity to sit together and complete something side by side, allowing them to share a moment of closeness.\nThe painting reflects her hope that Zixuan could still be the healthy, carefree child he was when he was younger. Perhaps it preserves not only a memory of childhood, but also a mother’s simplest wish: that this illness will be only one chapter in his journey, and that one day, his healthy self will return to everyday life.","session":8,"sessionOrderPosition":26,"age":"13 years old","ageOrderPosition":20},{"id":"27","image":"assets/art/27.jpg","name":"Yu","diagnosis":"Medulloblastoma","dateCreated":"August 21, 2026","description":"Seven-year-old Yu is from Guangxi. In March 2026, he was diagnosed with medulloblastoma. An MRI showed a large tumor in his cerebellum. Because he needed specialized pediatric cancer care, his family brought him to Zhujiang Hospital of Southern Medical University in Guangzhou. When they arrived, hospital beds were scarce, and Yu was also suffering from hydrocephalus. His family could only wait anxiously for a bed. He underwent surgery and two rounds of chemotherapy, and has just completed radiotherapy, with more treatment ahead.\nFor his mother, the surgery was the most difficult part to remember. The fear of that period is hard to put into words. After moving into a small family apartment through charitable support, however, Yu gradually became more relaxed. At seven, he remains a very dependent young child. When his father is around, he refuses to let him feed him; as soon as his mother arrives, he wants her to feed him. During painting, he also likes to lean against her and stay close.\nHis mother has found painting to be a way for them to relax together. Hospital volunteers provide coloring books and art materials, and whenever they have time, she paints with Yu. Painting gives them something to enjoy together and lets her step away from treatment anxiety.\nDuring this activity, Yu saw an old photo of himself and asked, “When was this me?” He seemed to have forgotten what he looked like then. Recreating the photograph in the painting was like helping him recover a piece of memory: the healthy, smiling child he was before illness. His mother hopes this can reduce his screen time, develop his interests, and create more moments of connection. To her, the painting does more than record Yu today. It reminds them that the healthy little boy who loved staying close to his mother is still there, and they are waiting for his return to that life.","session":8,"sessionOrderPosition":27,"age":"7 years old","ageOrderPosition":8},{"id":"28","image":"assets/art/28.jpg","name":"Zhang Huizhan","diagnosis":"Medulloblastoma","dateCreated":"August 21, 2026","description":"Thirteen-year-old Zhang Huizhan is from Yangjiang, Guangdong. On October 9 last year, he was diagnosed with malignant medulloblastoma. Because local medical resources were limited, his family brought him to Zhujiang Hospital of Southern Medical University in Guangzhou. After radiotherapy, he began chemotherapy. Radiation caused him to lose more than ten pounds, and his throat became ulcerated, making it difficult to eat. After chemotherapy, his blood counts repeatedly became unstable, requiring blood and platelet transfusions and injections to help his white blood cell counts recover. His condition is now gradually stabilizing, but treatment continues.\nFor his mother, caring for a child with cancer means more than accompanying him to the hospital. One of the hardest daily questions is, “What should he eat today?” Huizhan has a poor appetite, yet high-protein foods are essential during treatment. He has grown tired of eggs and refuses lean meat, so his mother keeps finding different ways to persuade him to eat. Without adequate nutrition, it is harder for his blood counts to recover. Treatment also brings practical difficulties: blood supplies can be limited, medications unavailable, and some drugs must be obtained from other cities. She has little time to dwell on her emotions and simply handles each problem as it comes.\nHuizhan understands his illness and knows what he is going through. Because he has lost his hair, he feels that he is “the ugliest” he has ever been and initially did not want to join the painting activity. His mother did not pressure him. She simply told him, “Whether you paint or not doesn’t matter. Your health matters most.” Her only wish was for the child in the painting to have his hair again. It is a simple hope: that one day, her son can return to being healthy and carefree. The painting does not need to record the illness. More than anything, she wants it to preserve the possibility that he will recover.","session":8,"sessionOrderPosition":28,"age":"13 years old","ageOrderPosition":21}];
  const byId = new Map(artworks.map((work) => [work.id, work]));
  const ageOrder = [...artworks].sort((a, b) => a.ageOrderPosition - b.ageOrderPosition);
  const sessions = [...new Set(artworks.map((work) => work.session))].sort((a, b) => a - b).map((session) => ({
    session,
    date: artworks.find((work) => work.session === session).dateCreated,
    works: artworks.filter((work) => work.session === session).sort((a, b) => a.sessionOrderPosition - b.sessionOrderPosition)
  }));
  const sessionRomanNumerals = ["I", "II", "III", "IV", "V", "VI", "VII", "VIII"];
  const xuan = byId.get("21");
  const riddlePath = "assets/art/21.1.jpg";
  const introText = `I wanted to create a space where they could pause, even if only for a moment. A paintbrush, a sheet of paper, a box of pigments—simple as they are—could be the first time in years that a caregiver created something not for a child’s treatment or a household bill, but for herself, and for the time they had journeyed through together. Painting does not demand answers, nor does it require explanation. It simply gives a caregiver the chance to become herself again.

Through painting, caregivers can also make their lives about more than pressure and tears. They can have the opportunity—and the ability—to create something beautiful.

That is the simplest wish behind the art-therapy sessions I initiated: although we cannot choose the illnesses that befall our families, we can still allow traces of beauty to remain in our own lives.

Please enjoy. The art created by 28 cancer caregivers.`;
  const processSteps = [
    { title: "I｜Choosing a Memory", text: "Some parents use the painting to capture an image of their child as they were before illness, holding onto the hope of seeing them return to that state. Others choose to remember this particular period of their child’s life. With a pencil, they carefully outline not only what they remember, but also the hopes they hold for their children.", image: "assets/steps/step%201.png", alt: "A caregiver beginning a painting with a pencil sketch" },
    { title: "II｜Tracing the Outline", text: "Once the pencil sketch is complete, they follow the lines with traditional Chinese painting pigments mixed with a little ink. Stroke by stroke, the familiar features begin to take shape.", image: "assets/steps/step%202.png", alt: "A caregiver tracing a pencil outline with ink and pigment" },
    { title: "III｜Bringing the Color", text: "They mix pigments with water and add the colors to their memory. Hair, clothes, the warmth of the cheeks—little by little, the figures begin to come alive on the paper.", image: "assets/steps/step%203.png", alt: "Color being added to a caregiver’s painting" },
    { title: "IV｜Restoring the Details", text: "The details of a child’s features and expression require more time and skill. After the parents complete the earlier stages, the artist help with the final details, using fenran, a traditional Chinese painting technique, to add depth around the eyes, nose, and cheeks. Little by little, the child they remember takes shape on the paper.", image: "assets/steps/step%204.png", alt: "An artist adding the final details to a child portrait" }
  ];
  const state = { view: 1, room: 0, activeStep: 0, activeAge: "", wrong: new Set(), attempts: 0, found: false };
  const page = document.getElementById("page-art-works");
  const dialog = document.getElementById("painting-dialog");
  const dialogBody = document.getElementById("painting-dialog-content");
  const nav = document.querySelector(".site-header");

  function escapeHtml(value) {
    return String(value).replace(/[&<>"']/g, (character) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[character]);
  }
  function title(work) { return `${work.name} | ${work.diagnosis}`; }
  function paragraphs(text) { return String(text).split(/\r?\n+/).map((part) => part.trim()).filter(Boolean).map((part) => `<p>${escapeHtml(part)}</p>`).join(""); }
  function tile(work, extra = "") {
    const label = title(work);
    return `<button class="aw-painting ${extra}" type="button" data-aw-id="${work.id}" data-painting-id="${work.id}" aria-label="Open ${escapeHtml(label)}"><img src="${work.image}" alt="${escapeHtml(label)}" loading="lazy"></button>`;
  }
  function arrow(label, nextView, extra = "") {
    return `<button type="button" class="aw-arrow ${extra}" data-aw-view="${nextView}" aria-label="${label}">→</button>`;
  }
  function viewFrame(view, content, className = "") {
    return `<div class="aw-view aw-view-${view} ${className}" data-aw-view-root="${view}">${content}</div>`;
  }
  function storyHeader(eyebrow, heading, subtitle = "") {
    return `<header class="aw-section-heading"><span class="eyebrow">${eyebrow}</span><h2>${heading}</h2>${subtitle ? `<p>${subtitle}</p>` : ""}</header>`;
  }

  function renderCanvas() {
    const width = window.innerWidth;
    const height = Math.max(320, window.innerHeight - (nav ? nav.offsetHeight : 0));
    const blocks = Array.from({ length: 25 }, (_, index) => `<div class="aw-canvas-block" style="width:${width}px;height:${height}px">${artworks.map((work) => tile(work, "aw-canvas-tile")).join("")}</div>`).join("");
    return viewFrame(1, `<section class="aw-canvas" aria-label="Infinite canvas of paintings"><div class="aw-repeat-grid" style="width:${width * 5}px;height:${height * 5}px;grid-template-columns:repeat(5,${width}px);grid-template-rows:repeat(5,${height}px)">${blocks}</div><div class="aw-canvas-hint">Move your pointer to explore</div>${arrow("Continue to introduction", 2, "aw-canvas-next")}</section>`);
  }

  function renderStory() {
    const cards = processSteps.map((step, index) => `<button type="button" class="aw-process-card ${index === state.activeStep ? "is-active" : ""}" data-aw-step="${index}" aria-expanded="${index === state.activeStep}" style="--step-image:url('${step.image}')"><span class="aw-process-shade"></span><span class="aw-process-copy"><strong>${escapeHtml(step.title)}</strong><span>${escapeHtml(step.text)}</span></span><img src="${step.image}" alt="${escapeHtml(step.alt)}" loading="lazy"></button>`).join("");
    return viewFrame(2, `<section class="aw-story-intro"><div class="aw-story-copy"><span class="eyebrow">A note from Jinyuan</span><h1>Seeing HER Burdens &amp; Needs</h1><p>${escapeHtml(introText)}</p></div></section><section class="aw-process"><div class="aw-process-heading"><span class="eyebrow">The making of a memory</span><h2>From Memory to Art</h2></div><div class="aw-process-gallery">${cards}</div>${arrow("Continue to exhibition choices", 3, "aw-process-next")}</section>`, "aw-story");
  }

  function renderChoices() {
    const cards = `<div class="aw-choice-grid"><button type="button" class="aw-choice" data-aw-view="4"><span class="aw-choice-pre">In Sequence of</span><strong><em>Art Therapy</em></strong><span class="aw-choice-post">Sessions</span><span class="aw-choice-arrow">↗</span></button><button type="button" class="aw-choice" data-aw-view="5"><span class="aw-choice-pre">In Sequence of</span><strong><em>Age</em></strong><span class="aw-choice-post">of Children with Cancer</span><span class="aw-choice-arrow">↗</span></button></div>`;
    return viewFrame(3, `${storyHeader("Enter the exhibition", "Choose a Way to View", "Two paths through the same collection.")}${cards}`);
  }

  function renderRoom() {
    const session = sessions[state.room];
    const pieces = session.works.map((work) => tile(work, "aw-room-mat")).join("");
    const dots = sessions.map((item, index) => `<button type="button" class="aw-room-dot ${index === state.room ? "is-active" : ""}" data-aw-room="${index}" aria-label="Show room: ${escapeHtml(item.date)}" aria-current="${index === state.room ? "step" : "false"}"></button>`).join("");
    return viewFrame(4, `<section class="aw-session-view"><header class="aw-session-heading"><span class="eyebrow">Sequence of Art Therapy</span></header><div class="aw-room-stage"><div class="aw-room-cuboid"><div class="aw-room-face aw-back-wall"><div class="aw-session-plaque"><span class="aw-session-number">Session ${sessionRomanNumerals[state.room]}</span><time class="aw-session-date">${escapeHtml(session.date)}</time></div><div class="aw-room-artworks" style="--piece-count:${session.works.length}">${pieces}</div></div><div class="aw-room-face aw-left-wall" aria-hidden="true"></div><div class="aw-room-face aw-right-wall" aria-hidden="true"></div><div class="aw-room-face aw-ceiling" aria-hidden="true"></div><div class="aw-room-face aw-floor" aria-hidden="true"></div></div><button type="button" class="aw-room-arrow aw-prev" data-aw-room-shift="-1" aria-label="Previous session">←</button><button type="button" class="aw-room-arrow aw-next-room" data-aw-room-shift="1" aria-label="Next session">→</button></div><div class="aw-floor-plan" aria-label="Exhibition room map">${dots}</div>${arrow("Continue to the Who is she? game", 6, "aw-gallery-next")}</section>`);
  }

  function renderAge() {
    const columns = ageOrder.map((work) => `<button type="button" class="aw-age-column" data-aw-id="${work.id}" data-aw-age="${work.id}" aria-label="${escapeHtml(title(work))}, ${escapeHtml(work.age)}"><span class="aw-age-meta"><strong>${escapeHtml(work.age)}</strong><small>${escapeHtml(work.diagnosis)}</small></span><img src="${work.image}" alt="${escapeHtml(title(work))}" loading="lazy"><span class="aw-age-name">${escapeHtml(work.name)}</span></button>`).join("");
    return viewFrame(5, `<section class="aw-age-view">${storyHeader("Follow the paintings", "Age")}<div class="aw-age-columns" aria-label="Paintings ordered from youngest to oldest">${columns}</div>${arrow("Continue to the Who is she? game", 6, "aw-age-next")}</section>`);
  }

  function renderGuess() {
    if (state.found) {
      const tries = `${state.attempts} ${state.attempts === 1 ? "try" : "tries"}`;
      return viewFrame(6, `<section class="aw-guess-view aw-guess-view-found"><header class="aw-guess-heading"><span class="eyebrow">A small mystery</span><h2>Who is she?</h2></header><div class="aw-guess-result"><div class="aw-result-pair"><button type="button" data-aw-riddle aria-label="Open ${escapeHtml(title(xuan))}"><img src="${riddlePath}" alt="${escapeHtml(title(xuan))}"></button><button type="button" data-aw-id="21" data-painting-id="21" aria-label="Open ${escapeHtml(title(xuan))}"><img src="${xuan.image}" alt="${escapeHtml(title(xuan))}"></button></div><p>You found her in ${tries}.</p><div class="aw-xuan-caption">${escapeHtml(typeof SITE_DATA !== "undefined" && SITE_DATA.xuanStory ? SITE_DATA.xuanStory : xuan.description)}</div><div class="aw-guess-actions"><button type="button" class="aw-text-button" data-aw-reset>Play again</button><button type="button" class="aw-text-button" data-aw-view="3">Choose how to view the exhibition</button>${arrow("Continue to the final gallery", 7, "aw-guess-next")}</div></div></section>`);
    }
    const tiles = artworks.map((work) => `<button type="button" class="aw-painting aw-guess-tile ${state.wrong.has(work.id) ? "is-gone" : ""}" data-aw-id="${work.id}" aria-label="Guess ${escapeHtml(title(work))}" ${state.wrong.has(work.id) ? "disabled aria-hidden=\"true\" tabindex=\"-1\"" : ""}><img src="${work.image}" alt="${escapeHtml(title(work))}" loading="lazy"></button>`).join("");
    return viewFrame(6, `<section class="aw-guess-view"><header class="aw-guess-heading"><span class="eyebrow">A small mystery</span><h2>Who is she?</h2><p>Which painting in the gallery portrays the same girl?</p></header><div class="aw-guess-controls"><button type="button" class="aw-return-link" data-aw-view="3"><span aria-hidden="true">←</span> Choose a Way to View</button></div><button type="button" class="aw-riddle-button" data-aw-riddle aria-label="Open ${escapeHtml(title(xuan))}"><img class="aw-riddle-image" src="${riddlePath}" alt="${escapeHtml(title(xuan))}"></button><div class="aw-guess-grid">${tiles}</div><p class="aw-attempts" aria-live="polite">Attempts: ${state.attempts}</p></section>`);
  }

  function renderFinal() {
    return viewFrame(7, `<section class="aw-final-view">${storyHeader("Stay as long as you like", "Final Gallery", "Click any painting to read its story.")}<div class="aw-final-grid">${artworks.map((work) => tile(work, "aw-final-tile")).join("")}</div><p class="aw-final-footer">Made with love for every child and every caregiver.</p><button type="button" class="aw-text-button aw-back-beginning" data-aw-beginning>Back to the beginning</button></section>`);
  }

  function renderArt() {
    if (!page) return;
    const renderers = { 1: renderCanvas, 2: renderStory, 3: renderChoices, 4: renderRoom, 5: renderAge, 6: renderGuess, 7: renderFinal };
    page.innerHTML = renderers[state.view]();
    window.scrollTo({ top: 0, left: 0, behavior: "instant" });
    const canvas = page.querySelector(".aw-canvas");
    if (canvas) {
      canvas.addEventListener("mousemove", (event) => {
        const x = (event.clientX / window.innerWidth - 0.5) * 0.88;
        const y = (event.clientY - canvas.getBoundingClientRect().top) / canvas.clientHeight - 0.5;
        const grid = canvas.querySelector(".aw-repeat-grid");
        grid.style.transform = `translate3d(calc(-50% - ${x * window.innerWidth}px),calc(-50% - ${y * canvas.clientHeight}px),0)`;
      });
    }
  }

  function openPaintingCard(id, imagePath) {
    const work = byId.get(String(id));
    if (!work || !dialog || !dialogBody) return;
    dialogBody.innerHTML = `<article class="aw-dialog-card"><img class="aw-dialog-image" src="${imagePath || work.image}" alt="${escapeHtml(title(work))}"><div class="aw-dialog-copy"><h2>${escapeHtml(title(work))}</h2><p class="aw-date-created">Date Created | ${escapeHtml(work.dateCreated)}</p><div class="aw-description">${paragraphs(work.description)}</div></div></article>`;
    dialog.showModal();
    dialog.querySelector(".dialog-close").focus();
  }

  function resetArtWorks() {
    state.view = 1;
    state.room = 0;
    state.activeStep = 0;
    state.activeAge = "";
    state.wrong.clear();
    state.attempts = 0;
    state.found = false;
    if (dialog.open) dialog.close();
    renderArt();
    window.scrollTo({ top: 0, left: 0, behavior: "instant" });
  }

  page.addEventListener("click", (event) => {
    const target = event.target instanceof Element ? event.target : null;
    if (!target) return;
    if (target.closest("[data-aw-beginning]")) { state.wrong.clear(); state.attempts = 0; state.found = false; state.view = 1; renderArt(); return; }
    const viewButton = target.closest("[data-aw-view]");
    if (viewButton) {
      event.preventDefault();
      state.view = Number(viewButton.dataset.awView);
      if (state.view === 4) state.room = 0;
      renderArt();
      return;
    }
    const roomShift = target.closest("[data-aw-room-shift]");
    if (roomShift) {
      state.room = (state.room + Number(roomShift.dataset.awRoomShift) + sessions.length) % sessions.length;
      renderArt();
      return;
    }
    const roomDot = target.closest("[data-aw-room]");
    if (roomDot) { state.room = Number(roomDot.dataset.awRoom); renderArt(); return; }
    if (target.closest("[data-aw-reset]")) { state.wrong.clear(); state.attempts = 0; state.found = false; renderArt(); return; }
    if (target.closest("[data-aw-riddle]")) { openPaintingCard(xuan.id, riddlePath); return; }
    if (state.view === 4) {
      const hitElement = document.elementsFromPoint(event.clientX, event.clientY).find((element) => element instanceof Element && element.closest("[data-painting-id]"));
      const roomPainting = target.closest("[data-painting-id]") || (hitElement && hitElement.closest("[data-painting-id]"));
      if (roomPainting) { openPaintingCard(roomPainting.dataset.paintingId); return; }
    }
    const artworkButton = target.closest("[data-aw-id]");
    if (artworkButton) {
      const work = byId.get(artworkButton.dataset.awId);
      if (!work) return;
      if (state.view === 6 && !state.found) {
        state.attempts += 1;
        if (work.id === "21") state.found = true;
        else state.wrong.add(work.id);
        renderArt();
      } else openPaintingCard(work.id);
    }
  });

  page.addEventListener("mouseover", (event) => {
    const column = event.target instanceof Element ? event.target.closest("[data-aw-age]") : null;
    if (column) page.querySelectorAll(".aw-age-column.is-active").forEach((item) => item.classList.remove("is-active")), column.classList.add("is-active");
    const step = event.target instanceof Element ? event.target.closest("[data-aw-step]") : null;
    if (step) { state.activeStep = Number(step.dataset.awStep); page.querySelectorAll(".aw-process-card").forEach((item, index) => item.classList.toggle("is-active", index === state.activeStep)); }
  });
  page.addEventListener("mouseout", (event) => {
    const column = event.target instanceof Element ? event.target.closest("[data-aw-age]") : null;
    if (column && !column.contains(event.relatedTarget)) column.classList.remove("is-active");
  });
  page.addEventListener("focusin", (event) => {
    const step = event.target instanceof Element ? event.target.closest("[data-aw-step]") : null;
    if (step) { state.activeStep = Number(step.dataset.awStep); page.querySelectorAll(".aw-process-card").forEach((item, index) => item.classList.toggle("is-active", index === state.activeStep)); }
  });
  page.addEventListener("wheel", (event) => {
    if (state.view !== 4 || Math.abs(event.deltaY) < 18) return;
    event.preventDefault();
    state.room = Math.max(0, Math.min(sessions.length - 1, state.room + (event.deltaY > 0 ? 1 : -1)));
    renderArt();
  }, { passive: false });
  document.addEventListener("click", (event) => {
    const close = event.target instanceof Element ? event.target.closest(".dialog-close") : null;
    if (close && dialog.open) dialog.close();
    if (event.target === dialog && dialog.open) dialog.close();
  });
  window.addEventListener("keydown", (event) => {
    if (state.view === 4 && !dialog.open && (event.key === "ArrowLeft" || event.key === "ArrowRight")) {
      state.room = Math.max(0, Math.min(sessions.length - 1, state.room + (event.key === "ArrowRight" ? 1 : -1)));
      renderArt();
    }
  });

  // Keep a single persistent delegated listener at the art page root as room faces are re-rendered.
  window.renderArt = renderArt;
  window.resetArtWorks = resetArtWorks;
  document.addEventListener("click", (event) => {
    const artLink = event.target instanceof Element && event.target.closest('.main-nav a[href="#art-works"], a[data-page="art-works"]');
    if (artLink) resetArtWorks();
  });
  window.addEventListener("hashchange", () => { if (location.hash === "#art-works") resetArtWorks(); });
  window.addEventListener("resize", () => { if (state.view === 1) renderArt(); });
  if (location.hash === "#art-works") resetArtWorks();
})();
